//! weft-core: requirement record parsing, canonical hashing, and verification.

use serde::Deserialize;
use sha2::{Digest, Sha256};
use unicode_normalization::UnicodeNormalization;

/// The lifecycle state of a requirement record.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    Active,
    Deprecated,
}

/// A single requirement record, parsed from a `docs/prds/**/*.toml` file.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct Requirement {
    pub id: String,
    pub version: u32,
    pub feat: Option<String>,
    pub hash: String,
    pub status: Status,
    pub statement: String,
    pub acceptance: Vec<String>,
    pub rationale: Option<String>,
    pub notes: Option<String>,
}

impl Requirement {
    /// Parses a requirement record from its TOML source.
    pub fn parse(toml_src: &str) -> Result<Requirement, toml::de::Error> {
        toml::from_str(toml_src)
    }
}

/// Computes the Content Hash for a requirement's normative region: the
/// `statement` (trimmed) plus each `acceptance` item (trimmed), joined with
/// `\n`, NFC-normalized, then SHA-256, truncated to the first 8 hex chars.
pub fn canonical_hash(statement: &str, acceptance: &[String]) -> String {
    let mut parts: Vec<String> = Vec::with_capacity(1 + acceptance.len());
    parts.push(statement.trim().to_string());
    parts.extend(acceptance.iter().map(|item| item.trim().to_string()));
    let canonical: String = parts.join("\n").nfc().collect();

    let digest = Sha256::digest(canonical.as_bytes());
    digest.iter().take(4).map(|b| format!("{b:02x}")).collect()
}
---REQ TEST---
use weft_core::{canonical_hash, verify_requirement, Requirement, Status, VerifyIssue};

const STATEMENT: &str = "The system must allow users to log in with email and password.";
const ACCEPTANCE: &[&str] = &[
    "Given valid credentials, the user is authenticated.",
    "Given invalid credentials, an error is shown.",
];

fn fixture_toml(hash: &str, id: &str) -> String {
    format!(
        r#"
id = "{id}"
version = 1
feat = "FEAT-Auth"
hash = "{hash}"
status = "active"
statement = "{STATEMENT}"

acceptance = [
    "{a0}",
    "{a1}",
]

rationale = "Login is the entry point for all authenticated features."
"#,
        a0 = ACCEPTANCE[0],
        a1 = ACCEPTANCE[1],
    )
}

fn current_hash() -> String {
    let acceptance: Vec<String> = ACCEPTANCE.iter().map(|s| s.to_string()).collect();
    canonical_hash(STATEMENT, &acceptance)
}

#[test]
fn parses_a_well_formed_requirement_record() {
    let hash = current_hash();
    let toml_src = fixture_toml(&hash, "REQ-001");

    let req = Requirement::parse(&toml_src).expect("should parse");

    assert_eq!(req.id, "REQ-001");
    assert_eq!(req.version, 1);
    assert_eq!(req.feat.as_deref(), Some("FEAT-Auth"));
    assert_eq!(req.hash, hash);
    assert_eq!(req.status, Status::Active);
    assert_eq!(req.statement, STATEMENT);
    assert_eq!(req.acceptance.len(), 2);
}

#[test]
fn well_formed_record_with_current_hash_passes_verification() {
    let hash = current_hash();
    let toml_src = fixture_toml(&hash, "REQ-001");
    let req = Requirement::parse(&toml_src).expect("should parse");

    let issues = verify_requirement(&req, "REQ-001");

    assert!(issues.is_empty(), "expected no issues, got {issues:?}");
}

#[test]
fn stale_stored_hash_fails_verification_with_bump_message() {
    let toml_src = fixture_toml("deadbeef", "REQ-001");
    let req = Requirement::parse(&toml_src).expect("should parse");

    let issues = verify_requirement(&req, "REQ-001");

    assert_eq!(issues.len(), 1);
    match &issues[0] {
        VerifyIssue::HashMismatch { stored, derived } => {
            assert_eq!(stored, "deadbeef");
            assert_eq!(derived, &current_hash());
        }
        other => panic!("expected HashMismatch, got {other:?}"),
    }
    assert!(issues[0].to_string().contains("weft bump REQ-001"));
}

#[test]
fn id_not_matching_filename_fails_verification() {
    let hash = current_hash();
    let toml_src = fixture_toml(&hash, "REQ-001");
    let req = Requirement::parse(&toml_src).expect("should parse");

    let issues = verify_requirement(&req, "REQ-002");

    assert!(issues
        .iter()
        .any(|i| matches!(i, VerifyIssue::IdFilenameMismatch { .. })));
}

#[test]
fn malformed_id_fails_verification() {
    let hash = current_hash();
    let toml_src = fixture_toml(&hash, "REQ-1");
    let req = Requirement::parse(&toml_src).expect("should parse");

    let issues = verify_requirement(&req, "REQ-1");

    assert!(issues
        .iter()
        .any(|i| matches!(i, VerifyIssue::InvalidIdFormat(_))));
}

#[test]
fn empty_acceptance_fails_verification() {
    let toml_src = format!(
        r#"
id = "REQ-001"
version = 1
hash = "00000000"
status = "active"
statement = "{STATEMENT}"
acceptance = []
"#
    );
    let req = Requirement::parse(&toml_src).expect("should parse");

    let issues = verify_requirement(&req, "REQ-001");

    assert!(issues
        .iter()
        .any(|i| matches!(i, VerifyIssue::EmptyAcceptance)));
}
---HASH TEST---
use weft_core::canonical_hash;

#[test]
fn same_text_produces_same_eight_hex_char_hash() {
    let statement = "The system must allow users to log in.";
    let acceptance = vec![
        "Given valid credentials, the user is authenticated.".to_string(),
        "Given invalid credentials, an error is shown.".to_string(),
    ];

    let hash = canonical_hash(statement, &acceptance);

    assert_eq!(hash.len(), 8);
    assert!(hash.chars().all(|c| c.is_ascii_hexdigit()));
    assert_eq!(hash, canonical_hash(statement, &acceptance));
}

#[test]
fn surrounding_whitespace_does_not_affect_hash() {
    let trimmed = canonical_hash(
        "The system must allow users to log in.",
        &["Given valid credentials, the user is authenticated.".to_string()],
    );

    let padded = canonical_hash(
        "  The system must allow users to log in.\n",
        &["  Given valid credentials, the user is authenticated.  ".to_string()],
    );

    assert_eq!(trimmed, padded);
}

#[test]
fn reordering_acceptance_criteria_changes_the_hash() {
    let statement = "The system must allow users to log in.";
    let original = vec![
        "Criterion A".to_string(),
        "Criterion B".to_string(),
    ];
    let reordered = vec![
        "Criterion B".to_string(),
        "Criterion A".to_string(),
    ];

    assert_ne!(
        canonical_hash(statement, &original),
        canonical_hash(statement, &reordered)
    );
}

#[test]
fn unicode_normalization_makes_equivalent_text_hash_the_same() {
    // "é" as a single precomposed code point (NFC) vs. "e" + combining acute accent (NFD).
    let nfc = canonical_hash("Caf\u{00e9}", &["item".to_string()]);
    let nfd = canonical_hash("Cafe\u{0301}", &["item".to_string()]);

    assert_eq!(nfc, nfd);
}
